-- Tables for MariaDB 10.4+ / MySQL 8 (XAMPP). Apply with: npm run db:setup
-- The database itself (MYSQL_DATABASE) is created by setup.js. Safe to re-run:
-- every table is IF NOT EXISTS and the role rows are upserted.
--
-- No organizations: every account belongs to the studio and has exactly one role
-- (users.role_slug). What each role may do lives in role_permissions, filled from
-- src/utils/roles.js when the server starts (models/role.js ensureCatalog).
--
--   uuid        -> CHAR(36) ascii, generated by the app (crypto.randomUUID())
--   citext      -> VARCHAR + utf8mb4_unicode_ci (case-insensitive, so UNIQUE ignores case)
--   bytea       -> BINARY(32) for SHA-256/HMAC digests, VARBINARY for encrypted data
--   inet        -> VARCHAR(45) (fits IPv6)
--   timestamptz -> DATETIME(3) in UTC (each connection runs SET time_zone = '+00:00')

/* ---------- Roles and permissions ---------- */

-- One row per role. The slug is the key the app checks; rank orders them (higher = more access)
-- and stops anyone handing out a role above their own.
CREATE TABLE IF NOT EXISTS roles (
  slug        VARCHAR(30)  CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name        VARCHAR(60)  NOT NULL,
  description VARCHAR(255) NULL,
  `rank`      TINYINT UNSIGNED NOT NULL DEFAULT 0,
  is_staff    BOOLEAN      NOT NULL DEFAULT FALSE,    -- may open the photographer panel
  is_system   BOOLEAN      NOT NULL DEFAULT TRUE,     -- comes from utils/roles.js; not editable
  created_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (slug),
  CONSTRAINT ck_roles_slug CHECK (slug REGEXP '^[a-z][a-z_]{1,29}$')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- The roles must exist before any user row can point at one (users.role_slug defaults to 'client').
-- utils/roles.js stays the source of truth: the server updates names and permissions on start.
INSERT INTO roles (slug, name, `rank`, is_staff) VALUES
  ('client',       'Client',       10, FALSE),
  ('assistant',    'Assistant',    20, TRUE),
  ('editor',       'Editor',       30, TRUE),
  ('photographer', 'Photographer', 40, TRUE),
  ('studio_lead',  'Studio lead',  90, TRUE)
ON DUPLICATE KEY UPDATE slug = slug;

CREATE TABLE IF NOT EXISTS permissions (
  id          SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  code        VARCHAR(60)  CHARACTER SET ascii COLLATE ascii_bin NOT NULL, -- e.g. access_code.manage
  module      VARCHAR(30)  NOT NULL,
  description VARCHAR(255) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_permissions_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS role_permissions (
  role_slug     VARCHAR(30) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  permission_id SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (role_slug, permission_id),
  KEY ix_role_permissions_perm (permission_id),
  CONSTRAINT fk_rp_role FOREIGN KEY (role_slug) REFERENCES roles (slug) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_rp_perm FOREIGN KEY (permission_id) REFERENCES permissions (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/* ---------- Accounts ---------- */

-- Clients sign up on /login (role client, status pending until a studio lead approves them);
-- staff are created with npm run user:create (active straight away).
CREATE TABLE IF NOT EXISTS users (
  id                  CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  full_name           VARCHAR(100) NOT NULL,
  email               VARCHAR(254) NOT NULL,
  role_slug           VARCHAR(30)  CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'client',
  mobile              VARCHAR(16)  NULL,                -- +9779XXXXXXXXX (Nepal mobile)
  photo_key           VARCHAR(200) CHARACTER SET ascii COLLATE ascii_bin NULL, -- profile photo on R2: profiles/<id>/<random>.webp (staff)
  password_hash       VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, -- bcrypt
  email_verified_at   DATETIME(3)  NULL,                -- sign-in is refused until set
  totp_secret_enc     VARBINARY(255) NULL,              -- 2FA (not used by the app yet)
  totp_enabled_at     DATETIME(3)  NULL,
  terms_version       VARCHAR(20)  NULL,                -- TERMS_VERSION in .env when accepted
  terms_accepted_at   DATETIME(3)  NULL,                -- NULL for staff created from the command line
  failed_logins       INT          NOT NULL DEFAULT 0,  -- wrong passwords in a row
  locked_until        DATETIME(3)  NULL,                -- set after MAX_FAILED_ATTEMPTS
  password_changed_at DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3), -- older tokens stop working
  last_login_at       DATETIME(3)  NULL,
  status              VARCHAR(10)  NOT NULL DEFAULT 'pending',  -- pending: signed up, waiting for the studio to approve
  created_at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_email (email),
  KEY ix_users_role (role_slug),
  CONSTRAINT ck_users_full_name CHECK (CHAR_LENGTH(full_name) BETWEEN 2 AND 100),
  CONSTRAINT ck_users_email     CHECK (CHAR_LENGTH(email) <= 254),
  CONSTRAINT ck_users_mobile    CHECK (mobile REGEXP '^[+]9779[78][0-9]{8}$'),
  CONSTRAINT ck_users_failed    CHECK (failed_logins >= 0),
  CONSTRAINT ck_users_status    CHECK (status IN ('pending', 'active', 'disabled')),
  CONSTRAINT fk_users_role FOREIGN KEY (role_slug) REFERENCES roles (slug) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- user sessions: one row per login (device)
CREATE TABLE IF NOT EXISTS user_sessions (
  id           CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id      CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  token_hash   BINARY(32)   NOT NULL,                 -- SHA-256 of the current refresh token
  ip           VARCHAR(45)  NULL,
  user_agent   VARCHAR(512) NULL,
  remember     BOOLEAN      NOT NULL DEFAULT FALSE,   -- "Keep me signed in"
  created_at   DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  last_seen_at DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  expires_at   DATETIME(3)  NOT NULL,                 -- never extended by refreshing
  revoked_at   DATETIME(3)  NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_user_sessions_token (token_hash),
  KEY ix_user_sessions_active (user_id, revoked_at),
  CONSTRAINT fk_user_sessions_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- single-use tokens: email confirmation and password reset links, 6-digit codes for 2FA later
CREATE TABLE IF NOT EXISTS auth_tokens (
  id          CHAR(36)    CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id     CHAR(36)    CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  purpose     VARCHAR(20) NOT NULL,
  token_hash  BINARY(32)  NOT NULL,                  -- SHA-256 of a link token, HMAC of a code (utils/otp.js)
  attempts    INT         NOT NULL DEFAULT 0,        -- wrong guesses at a code
  expires_at  DATETIME(3) NOT NULL,
  used_at     DATETIME(3) NULL,                      -- set when used, replaced or out of attempts
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_auth_tokens_hash (token_hash),
  KEY ix_auth_tokens_open (user_id, purpose, used_at),
  CONSTRAINT ck_auth_tokens_purpose  CHECK (purpose IN ('verify_email', 'reset_password', 'login_2fa')),
  CONSTRAINT ck_auth_tokens_attempts CHECK (attempts >= 0),
  CONSTRAINT fk_auth_tokens_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- backup codes (for 2FA, not used yet)
CREATE TABLE IF NOT EXISTS user_backup_codes (
  id         CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id    CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  code_hash  VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  used_at    DATETIME(3)  NULL,
  PRIMARY KEY (id),
  KEY ix_user_backup_codes_user (user_id),
  CONSTRAINT fk_user_backup_codes_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- trusted devices: skip 2FA on a known browser (not used yet)
CREATE TABLE IF NOT EXISTS trusted_devices (
  id          CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id     CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  token_hash  BINARY(32)   NOT NULL,
  label       VARCHAR(255) NULL,                     -- "Chrome on Windows"
  expires_at  DATETIME(3)  NOT NULL,
  created_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_trusted_devices_token (token_hash),
  KEY ix_trusted_devices_user (user_id),
  CONSTRAINT fk_trusted_devices_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- the security log: sign-ins, failures, lockouts, resets, role changes, gallery codes opened
CREATE TABLE IF NOT EXISTS auth_events (
  id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id     CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NULL,
  email       VARCHAR(254) NULL,                     -- for failed sign-ins on unknown emails
  event       VARCHAR(30)  NOT NULL,
  ip          VARCHAR(45)  NULL,
  user_agent  VARCHAR(512) NULL,
  detail      JSON         NULL,
  at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY ix_auth_events_user (user_id, at),
  KEY ix_auth_events_ip (ip, at),
  KEY ix_auth_events_event (event, at),
  -- SET NULL: deleting a user keeps their history (the log is never rewritten otherwise).
  CONSTRAINT fk_auth_events_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/* ---------- Bookings ---------- */

-- A booking request from the website's booking form (Frontend/src/components/BookingForm.jsx):
-- the same fields, the same choices. A gallery code can point at the booking it was made for.
CREATE TABLE IF NOT EXISTS bookings (
  id           CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  client_name  VARCHAR(100) NOT NULL,                -- "Your name"
  email        VARCHAR(254) NOT NULL,                -- "Email"
  phone        VARCHAR(30)  NULL,                    -- "Phone" (optional)
  event_type   VARCHAR(40)  NOT NULL,                -- "Kind of event"
  event_date   DATE         NOT NULL,                -- "Date of the event"
  start_time   TIME         NULL,                    -- "Start time" (optional)
  venue        VARCHAR(200) NOT NULL,                -- "Venue and city"
  coverage     VARCHAR(40)  NULL,                    -- "Coverage" (optional)
  crew         TINYINT UNSIGNED NOT NULL DEFAULT 1,  -- "Photographers": 1 to 4
  notes        TEXT         NULL,                    -- "About the day" (optional)
  status       VARCHAR(12)  NOT NULL DEFAULT 'requested',
  user_id      CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NULL, -- the client's account, when signed in
  handled_by   CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NULL, -- the staff member looking after it
  source_ip    VARCHAR(45)  NULL,
  created_at   DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at   DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY ix_bookings_date (event_date),
  KEY ix_bookings_email (email),
  KEY ix_bookings_status (status, event_date),
  KEY ix_bookings_created (created_at, id),   -- the panel: newest first, ten at a time
  CONSTRAINT ck_bookings_name     CHECK (CHAR_LENGTH(client_name) BETWEEN 1 AND 100),
  CONSTRAINT ck_bookings_type     CHECK (event_type IN ('Wedding', 'Concert or festival', 'Conference or corporate event',
                                                        'Sport', 'Private celebration', 'Something else')),
  CONSTRAINT ck_bookings_coverage CHECK (coverage IS NULL OR coverage IN ('About 2 hours', 'Half a day (about 4 hours)',
                                                        'A full day (about 8 hours)', 'More than one day', 'Not sure yet')),
  CONSTRAINT ck_bookings_crew     CHECK (crew BETWEEN 1 AND 4),
  CONSTRAINT ck_bookings_status   CHECK (status IN ('requested', 'confirmed', 'dispatched', 'completed', 'cancelled')),
  CONSTRAINT fk_bookings_user     FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_bookings_handler  FOREIGN KEY (handled_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Who the studio sends to a booking (the panel's Bookings page, Send photographers): staff accounts.
CREATE TABLE IF NOT EXISTS booking_crew (
  booking_id   CHAR(36)    CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id      CHAR(36)    CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  assigned_by  CHAR(36)    CHARACTER SET ascii COLLATE ascii_bin NULL,
  assigned_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (booking_id, user_id),
  KEY ix_booking_crew_user (user_id),
  CONSTRAINT fk_booking_crew_booking  FOREIGN KEY (booking_id) REFERENCES bookings (id) ON DELETE CASCADE,
  CONSTRAINT fk_booking_crew_user     FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_booking_crew_assigner FOREIGN KEY (assigned_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- What a booking's client pays (the panel's Clients and Payments pages): each row is one payment, an
-- advance or the full payment, in Nepalese rupees. Asked for from Clients: the client is emailed the
-- amount with the studio's payment QR, and the studio marks it paid when the money arrives (or cancels
-- it). Recorded by hand on Payments (cash, a bank transfer): it starts as paid, with its method.
-- A paid one can be refunded (a cancelled booking).
CREATE TABLE IF NOT EXISTS bookings_payment (
  id            CHAR(36)      CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  booking_id    CHAR(36)      CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  kind          VARCHAR(10)   NOT NULL,                 -- advance | full
  amount_npr    DECIMAL(12,2) NOT NULL,
  status        VARCHAR(10)   NOT NULL DEFAULT 'requested', -- requested | paid | cancelled | refunded
  method        VARCHAR(10)   NULL,                     -- how it was paid, when known: cash | bank | esewa | khalti | fonepay
  note          VARCHAR(300)  NULL,                     -- written in the client's email
  email_to      VARCHAR(254)  NULL,
  emailed_at    DATETIME(3)   NULL,                     -- NULL: the email didn't go
  requested_by  CHAR(36)      CHARACTER SET ascii COLLATE ascii_bin NULL,
  paid_at       DATETIME(3)   NULL,
  paid_by       CHAR(36)      CHARACTER SET ascii COLLATE ascii_bin NULL, -- who recorded it as received
  refunded_at   DATETIME(3)   NULL,
  refunded_by   CHAR(36)      CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at    DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at    DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY ix_bookings_payment_booking (booking_id, created_at),
  KEY ix_bookings_payment_status (status),
  KEY ix_bookings_payment_created (created_at, id),
  KEY ix_bookings_payment_paid (paid_at),
  CONSTRAINT ck_bookings_payment_kind   CHECK (kind IN ('advance', 'full')),
  CONSTRAINT ck_bookings_payment_status CHECK (status IN ('requested', 'paid', 'cancelled', 'refunded')),
  CONSTRAINT ck_bookings_payment_method CHECK (method IS NULL OR method IN ('cash', 'bank', 'esewa', 'khalti', 'fonepay')),
  CONSTRAINT ck_bookings_payment_amount CHECK (amount_npr > 0),
  CONSTRAINT fk_bookings_payment_booking   FOREIGN KEY (booking_id) REFERENCES bookings (id) ON DELETE CASCADE,
  CONSTRAINT fk_bookings_payment_requester FOREIGN KEY (requested_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_bookings_payment_payer     FOREIGN KEY (paid_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_bookings_payment_refunder  FOREIGN KEY (refunded_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- One value per name for the whole studio. payment_qr_key: the studio's own payment QR on R2
-- (eSewa, Khalti, Fonepay or a bank's), attached to every payment request.
CREATE TABLE IF NOT EXISTS studio_settings (
  name        VARCHAR(40)  CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  value       VARCHAR(500) NULL,
  updated_by  CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NULL,
  updated_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (name),
  CONSTRAINT fk_studio_settings_user FOREIGN KEY (updated_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- A day a staff member is off (the panel's Photographers page, "Off today"): they show as off that
-- day and aren't offered when sending photographers. `day` is the studio's local date, sent by the panel.
CREATE TABLE IF NOT EXISTS staff_days_off (
  user_id    CHAR(36)    CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  day        DATE        NOT NULL,
  set_by     CHAR(36)    CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (user_id, day),
  KEY ix_staff_days_off_day (day),
  CONSTRAINT fk_staff_days_off_user   FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_staff_days_off_setter FOREIGN KEY (set_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/* ---------- Events ---------- */

-- An event made from the panel's Uploads page (New event): one folder on R2, events/<slug>/, that its
-- photographs go into. The name is the gallery's title and is unique (case-insensitive); the slug is
-- fixed when the event is made, so renaming it never moves the files.
CREATE TABLE IF NOT EXISTS events (
  id           CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name         VARCHAR(80)  NOT NULL,                -- "Event name"
  slug         VARCHAR(64)  CHARACTER SET ascii COLLATE ascii_bin NOT NULL, -- the folder: events/<slug>/
  kind         VARCHAR(20)  NOT NULL,                -- "Kind of event"
  event_date   DATE         NOT NULL,                -- "Date"
  venue        VARCHAR(200) NULL,                    -- "Venue" (optional)
  booking_id   CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NULL, -- "Booking" (optional): one event per booking
  client_id    CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NULL, -- "Client" (optional): a client account
  created_by   CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NULL, -- who made it
  created_at   DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),     -- and when
  updated_at   DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_events_name (name),
  UNIQUE KEY uq_events_slug (slug),
  UNIQUE KEY uq_events_booking (booking_id),
  KEY ix_events_date (event_date),
  KEY ix_events_client (client_id),
  CONSTRAINT ck_events_name    CHECK (CHAR_LENGTH(name) BETWEEN 1 AND 80),
  CONSTRAINT ck_events_slug    CHECK (slug REGEXP '^[a-z0-9]+(-[a-z0-9]+)*$'),
  CONSTRAINT ck_events_kind    CHECK (kind IN ('Wedding', 'Concert', 'Conference', 'Sport', 'Celebration')),
  CONSTRAINT fk_events_booking FOREIGN KEY (booking_id) REFERENCES bookings (id) ON DELETE SET NULL,
  CONSTRAINT fk_events_client  FOREIGN KEY (client_id) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_events_creator FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- An event's categories ("Categories" on the form): each is a folder inside the event,
-- events/<event slug>/<slug>/, and an album in the gallery.
CREATE TABLE IF NOT EXISTS event_categories (
  id         CHAR(36)    CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  event_id   CHAR(36)    CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name       VARCHAR(40) NOT NULL,
  slug       VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  position   TINYINT UNSIGNED NOT NULL DEFAULT 0,  -- the order on the form
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_event_categories_slug (event_id, slug),
  UNIQUE KEY uq_event_categories_event (id, event_id), -- lets event_media check a category is its own event's
  CONSTRAINT ck_event_categories_slug CHECK (slug REGEXP '^[a-z0-9]+(-[a-z0-9]+)*$'),
  CONSTRAINT fk_event_categories_event FOREIGN KEY (event_id) REFERENCES events (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- (tables made before event_media existed get the key here; a no-op otherwise)
ALTER TABLE event_categories ADD UNIQUE KEY IF NOT EXISTS uq_event_categories_event (id, event_id);

-- Every photograph and video uploaded to an event, kept in R2 under that event's own folder:
--   events/<event slug>/<category slug | uncategorised>/<file name>   the file itself
--   events/<event slug>/_previews/<id>.jpg                             its preview (made by the browser)
-- A file belongs to exactly one event. Its category, when it has one, must be a category of the same
-- event (fk_event_media_category is on both columns), and the API only ever reaches a file through
-- its event (WHERE event_id = ?), so one event's links can't open another's files.
-- status: 'pending' while the browser is still sending it to R2, 'ready' once R2 has it (checked).
-- A large file goes up in parts: upload_id is its R2 multipart upload and part_size the size of each
-- part (the last may be smaller) until it is complete; both are NULL for a file sent in one PUT.
CREATE TABLE IF NOT EXISTS event_media (
  id            CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  event_id      CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  category_id   CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NULL,  -- NULL: Uncategorised
  kind          VARCHAR(7)   NOT NULL,                                     -- photo | video | audio | graphic | model
  object_key    VARCHAR(400) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, -- where the file is on R2
  preview_key   VARCHAR(400) CHARACTER SET ascii COLLATE ascii_bin NULL,   -- its small JPEG, when one was made
  file_name     VARCHAR(200) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, -- the name on R2 (cleaned, unique in its folder)
  original_name VARCHAR(255) NOT NULL,                                     -- the name on the photographer's computer
  content_type  VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  size_bytes    BIGINT UNSIGNED NOT NULL,
  width         INT UNSIGNED NULL,                                         -- pixels, when the browser could read them
  height        INT UNSIGNED NULL,
  duration_ms   INT UNSIGNED NULL,                                         -- videos and audio
  file_modified_at DATETIME(3) NULL,                                       -- the file's date on the computer it came from
  etag          VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NULL,   -- R2's checksum of the stored file
  status        VARCHAR(7)   NOT NULL DEFAULT 'pending',
  upload_id     VARCHAR(512) CHARACTER SET ascii COLLATE ascii_bin NULL,   -- R2's multipart upload, while it is unfinished
  part_size     INT UNSIGNED NULL,                                         -- bytes in each part of it
  uploaded_by   CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),       -- when the upload began
  uploaded_at   DATETIME(3)  NULL,                                         -- when R2 had all of it
  updated_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_event_media_key (object_key),
  KEY ix_event_media_list (event_id, status, file_name, id),
  KEY ix_event_media_recent (event_id, status, uploaded_at),
  KEY ix_event_media_category (category_id, event_id),
  KEY ix_event_media_uploader (uploaded_by),
  CONSTRAINT ck_event_media_kind   CHECK (kind IN ('photo', 'video', 'audio', 'graphic', 'model')),
  CONSTRAINT ck_event_media_status CHECK (status IN ('pending', 'ready')),
  CONSTRAINT ck_event_media_size   CHECK (size_bytes > 0),
  CONSTRAINT fk_event_media_event    FOREIGN KEY (event_id) REFERENCES events (id) ON DELETE CASCADE,
  CONSTRAINT fk_event_media_category FOREIGN KEY (category_id, event_id) REFERENCES event_categories (id, event_id),
  CONSTRAINT fk_event_media_uploader FOREIGN KEY (uploaded_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/* ---------- Gallery codes ---------- */

-- The code on a client's card or QR code (4-4-4-2 letters and digits, like ANNA-LEO1-JUNE-24) opens
-- their gallery without an account, as a client. Only an HMAC of the code is searchable (code_hash);
-- the code itself is kept AES-256-GCM encrypted (code_enc) so the panel can show and print it again.
CREATE TABLE IF NOT EXISTS gallery_codes (
  id             CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  code_hash      BINARY(32)   NOT NULL,
  code_enc       VARBINARY(128) NOT NULL,
  event_name     VARCHAR(120) NOT NULL,
  label          VARCHAR(80)  NULL,                  -- "Guests", "Family"
  event_id       CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NULL, -- the event (folder) it opens
  booking_id     CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NULL, -- the booking it was made for
  max_users      SMALLINT UNSIGNED NULL,             -- browsers that may view at the same time; NULL = no limit
  expires_at     DATETIME(3)  NULL,                  -- NULL: until revoked
  revoked_at     DATETIME(3)  NULL,
  revoked_by     CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NULL,
  open_count     INT UNSIGNED NOT NULL DEFAULT 0,    -- times it has been opened
  last_opened_at DATETIME(3)  NULL,
  created_by     CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NULL, -- who made it
  created_at     DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),     -- and when
  updated_at     DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_gallery_codes_hash (code_hash),
  KEY ix_gallery_codes_booking (booking_id),
  UNIQUE KEY uq_gallery_codes_event (event_id),   -- one code per event (regenerated in place)
  KEY ix_gallery_codes_created (created_at),
  CONSTRAINT ck_gallery_codes_max     CHECK (max_users IS NULL OR max_users > 0),
  CONSTRAINT fk_gallery_codes_booking FOREIGN KEY (booking_id) REFERENCES bookings (id) ON DELETE SET NULL,
  CONSTRAINT fk_gallery_codes_event   FOREIGN KEY (event_id) REFERENCES events (id) ON DELETE CASCADE,
  CONSTRAINT fk_gallery_codes_creator FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_gallery_codes_revoker FOREIGN KEY (revoked_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Client accounts that hold a gallery (the code given at sign-up, or opened while signed in).
CREATE TABLE IF NOT EXISTS gallery_code_members (
  code_id   CHAR(36)    CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id   CHAR(36)    CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  added_via VARCHAR(10) NOT NULL DEFAULT 'code',
  added_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (code_id, user_id),
  KEY ix_gallery_code_members_user (user_id),
  CONSTRAINT ck_gcm_via  CHECK (added_via IN ('signup', 'code', 'booking', 'staff')),
  CONSTRAINT fk_gcm_code FOREIGN KEY (code_id) REFERENCES gallery_codes (id) ON DELETE CASCADE,
  CONSTRAINT fk_gcm_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- One row per browser viewing a gallery. The HttpOnly gallery cookie holds the token; only its SHA-256
-- is kept. A seat counts against max_users while it was seen in the last few minutes.
CREATE TABLE IF NOT EXISTS gallery_code_sessions (
  id           CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  code_id      CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id      CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NULL, -- a signed-in client, else a guest
  role         VARCHAR(30)  NOT NULL DEFAULT 'client', -- whoever holds a gallery views it as a client, always
  via          VARCHAR(10)  NOT NULL DEFAULT 'code',   -- 'code' (typed, scanned or a QR link) or 'account'
  token_hash   BINARY(32)   NOT NULL,
  ip           VARCHAR(45)  NULL,
  user_agent   VARCHAR(512) NULL,
  created_at   DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  last_seen_at DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  expires_at   DATETIME(3)  NOT NULL,
  ended_at     DATETIME(3)  NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_gallery_code_sessions_token (token_hash),
  KEY ix_gallery_code_sessions_live (code_id, ended_at, last_seen_at),
  KEY ix_gallery_code_sessions_user (user_id, code_id, via, created_at),
  CONSTRAINT ck_gcs_role CHECK (role = 'client'),
  CONSTRAINT ck_gcs_via CHECK (via IN ('code', 'account')),
  CONSTRAINT fk_gcs_code FOREIGN KEY (code_id) REFERENCES gallery_codes (id) ON DELETE CASCADE,
  CONSTRAINT fk_gcs_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Wrong gallery codes per IP: GALLERY_CODE_MAX_ATTEMPTS within GALLERY_CODE_WINDOW_MINUTES blocks the
-- IP for GALLERY_CODE_BLOCK_MINUTES (services/gallerycode.js). Kept here, so a restart doesn't lift it.
CREATE TABLE IF NOT EXISTS gallery_code_blocks (
  ip                VARCHAR(45)  NOT NULL,
  failures          INT UNSIGNED NOT NULL DEFAULT 0,
  window_started_at DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  last_failure_at   DATETIME(3)  NULL,
  blocked_until     DATETIME(3)  NULL,
  times_blocked     INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (ip),
  KEY ix_gallery_code_blocks_until (blocked_until)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/* ---------- Packages and hire payments ---------- */

CREATE TABLE IF NOT EXISTS packages (
  id            CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  slug          VARCHAR(30)  CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name          VARCHAR(60)  NOT NULL,
  description   VARCHAR(255) NULL,
  price_monthly DECIMAL(12,2) NOT NULL DEFAULT 0,   -- NPR
  price_yearly  DECIMAL(12,2) NOT NULL DEFAULT 0,
  currency      CHAR(3)      CHARACTER SET ascii NOT NULL DEFAULT 'NPR',
  max_users     INT          NULL,                  -- NULL = unlimited
  max_invoices_per_month INT NULL,
  trial_days    SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  is_active     BOOLEAN      NOT NULL DEFAULT TRUE, -- hide retired packages from new buyers
  sort_order    TINYINT UNSIGNED NOT NULL DEFAULT 0,
  created_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_packages_slug (slug),
  CONSTRAINT ck_packages_price CHECK (price_monthly >= 0 AND price_yearly >= 0),
  CONSTRAINT ck_packages_users CHECK (max_users IS NULL OR max_users > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS package_features (
  package_id  CHAR(36)    CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  feature     VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  limit_value INT         NULL,                     -- NULL = unlimited/on
  PRIMARY KEY (package_id, feature),
  CONSTRAINT fk_package_features_package FOREIGN KEY (package_id) REFERENCES packages (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- A client paying for a package (was tied to organization subscriptions; now to the client's account).
CREATE TABLE IF NOT EXISTS hire_payments (
  id              CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id         CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  package_id      CHAR(36)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  amount          DECIMAL(12,2) NOT NULL,
  vat_amount      DECIMAL(12,2) NOT NULL DEFAULT 0,  -- 13% VAT
  currency        CHAR(3)      CHARACTER SET ascii NOT NULL DEFAULT 'NPR',
  gateway         VARCHAR(20)  NOT NULL,
  gateway_ref     VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NULL, -- gateway transaction id
  status          VARCHAR(10)  NOT NULL DEFAULT 'pending',
  period_start    DATETIME(3)  NOT NULL,
  period_end      DATETIME(3)  NOT NULL,
  invoice_no      VARCHAR(30)  NULL,                 -- the tax invoice to the client
  raw_response    JSON         NULL,                 -- verification response, for disputes
  paid_at         DATETIME(3)  NULL,
  created_at      DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_hire_payments_gateway (gateway, gateway_ref), -- the same payment can't be credited twice
  UNIQUE KEY uq_hire_payments_invoice (invoice_no),
  KEY ix_hire_payments_user (user_id, created_at),
  KEY ix_hire_payments_package (package_id),
  CONSTRAINT ck_hire_payments_status  CHECK (status IN ('pending','paid','failed','refunded')),
  CONSTRAINT ck_hire_payments_gateway CHECK (gateway IN ('esewa','khalti','connectips','fonepay','bank','manual')),
  CONSTRAINT ck_hire_payments_amount  CHECK (amount >= 0 AND vat_amount >= 0),
  CONSTRAINT ck_hire_payments_period  CHECK (period_end > period_start),
  CONSTRAINT fk_hire_payments_user    FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT,
  CONSTRAINT fk_hire_payments_package FOREIGN KEY (package_id) REFERENCES packages (id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

